import { Box, TextField, Typography, Button, FormGroup, FormControlLabel, Checkbox, CircularProgress, useMediaQuery } from "@mui/material";
import axios from "axios";
import { useState } from "react";
import config from "../config";
import { useNavigate, Link } from "react-router-dom";

export default function SignUp() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState("");
    const [password1, setPassword1] = useState("");
    const [autoLogin, setAutoLogin] = useState(false);
    const [emailError, setEmailError] = useState("");
    const [password1Error, setPassword1Error] = useState("");
    const [sginupError, setSignUpError] = useState("");

    const isSmallScreen = useMediaQuery('(max-width:600px)');

    const validateEmail = () => {
        if (email.trim() === "") {
            setEmailError("メールアドレスを入力してください");
        } else if (!email.includes("@")) {
            setEmailError("無効なメールアドレスです");
        } else {
            setEmailError("");
        }
    };

    const handleEmailChange = (event) => {
        setEmail(event.target.value);

        if (emailError) {
            setEmailError("");
        }
    };

    const validatePassword1 = () => {
        if (password1.trim() === "") {
            setPassword1Error("パスワードを入力してください");
        } else if (password1.length <= 5) {
            setPassword1Error("パスワードは6文字以上で入力してください");
        } else if (!/[a-zA-Z]/.test(password1) || !/[0-9]/.test(password1)) {
            setPassword1Error("パスワードには英字と数字の両方を含めてください");
        } else {
            setPassword1Error("");
        }
    };

    const handlePassword1Change = (event) => {
        setPassword1(event.target.value);

        if (password1Error) {
            setPassword1Error("");
        }
    };

    const handleCheckBox = () => {
        setAutoLogin(!autoLogin);
    };

    const handleLogin = async () => {
        if (email !== "" && password1 !== "" && emailError === "" && password1Error === "") {
            setLoading(true);

            const response = await axios.post(`${config.serverURL}/api/signup`, { email: email, password: password1, autoLogin: autoLogin });
            const data = response.data;

            if (data.success) {
                navigate("/home");
            } else {
                setSignUpError(data.error);
            }

            setLoading(false);
        } else {
            validateEmail();
            validatePassword1();
        }
    };

    return (
        <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            height="100vh"
            width="100vw"
            margin="0"
            padding="0"
            position="fixed"
            top="0"
            left="0"
            bgcolor={isSmallScreen ? "white" : "whitesmoke"}
        >
            <Box
                style={isSmallScreen ? {
                    textAlign: "center"
                } : {
                    backgroundColor: "white",
                    borderRadius: "8px",
                    padding: "40px",
                    boxShadow: "0 0 10px rgba(0, 0, 0, 0.2)",
                    textAlign: "center",
                    width: "90%",
                    maxWidth: "400px",
                    backdropFilter: "blur(10px)",
                    WebkitBackdropFilter: "blur(10px)",
                }}
            >
                <Typography fontWeight="bold" fontSize="25px" mb="30px" color="black">
                    VSpaceへログイン
                </Typography>
                <TextField
                    id="email"
                    label="メールアドレス"
                    variant="outlined"
                    fullWidth
                    style={{ marginBottom: "25px" }}
                    value={email}
                    onBlur={validateEmail}
                    error={Boolean(emailError)}
                    helperText={emailError}
                    onChange={handleEmailChange}
                />
                <TextField
                    id="password"
                    label="パスワード"
                    variant="outlined"
                    type="password"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                    value={password1}
                    onBlur={validatePassword1}
                    error={Boolean(password1Error)}
                    helperText={password1Error}
                    onChange={handlePassword1Change}
                />
                <TextField
                    id="password"
                    label="パスワード確認"
                    variant="outlined"
                    type="password"
                    fullWidth
                    style={{ marginBottom: "15px" }}
                    value={password1}
                    onBlur={validatePassword2}
                    error={Boolean(password2Error)}
                    helperText={password2Error}
                    onChange={handlePassword2Change}
                />
                <FormGroup style={{ marginBottom: "15px" }}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                sx={{
                                    color: "black",
                                    "&.Mui-checked": {
                                        color: "black"
                                    },
                                }}
                                onClick={handleCheckBox}
                            />
                        }
                        label="自動ログイン"
                    />
                </FormGroup>
                <Box mb="20px">
                    <Button
                        variant="contained"
                        fullWidth
                        disabled={loading}
                        style={{ padding: "15px", backgroundColor: "black", color: "white" }}
                        onClick={handleLogin}
                    >
                        ログイン
                        {loading && (
                            <Box position="absolute" display="flex" justifyContent="center" alignItems="center" width="50%" height="50%" bgcolor="black">
                                <CircularProgress size="20px" style={{ color: "white" }} />
                            </Box>
                        )}
                    </Button>
                </Box>
                <Typography>
                    アカウントをお持ちでない方は
                    <Link to="/signup" style={{ color: "blue" }}>
                        サインアップ
                    </Link>
                </Typography>
            </Box>
        </Box>
    );
}
